import{_ as o,a0 as n,w as d,s,ao as e,I as r,x as i,a1 as u,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"在 Linux 上用 Audacity 編輯音頻 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 Audacity 編輯音頻 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 Audacity 編輯音頻 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 Audacity 編輯音頻 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20211201 Edit audio on Linux with Audacity","title":"在 Linux 上用 Audacity 編輯音頻","tag":"202201","desc":""},"relativePath":"202201/20211201 Edit audio on Linux with Audacity.md","filePath":"[post].md"}'),p={name:"202201/20211201 Edit audio on Linux with Audacity.md"};function y(b,t,m,f,g,A){const a=n("Link");return d(),s("div",null,[t[51]||(t[51]=e('<h1 id="在-linux-上用-audacity-編輯音頻" tabindex="-1">在 Linux 上用 Audacity 編輯音頻 <a class="header-anchor" href="#在-linux-上用-audacity-編輯音頻" aria-label="Permalink to “在 Linux 上用 Audacity 編輯音頻”">​</a></h1><blockquote><p>Audacity 是開源軟件世界中的一個經典的強大工具，可以用於錄音、編輯等對聲音進行操作。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202201/09/130245b7jozrrrc7gorgae.jpg" alt=""></p><p>Audacity 聲音編輯器是填補了一個似乎沒有人意識到的空白的開源應用程序。它最初是在卡內基梅隆大學開發的，當時很多人還認為電腦只是用來辦公和學習的，要進行嚴肅的多媒體工作需要特殊的 DSP 外圍設備。Audacity 認識到，普通計算機用户偶爾也需要編輯音頻。在此後的 20 年裏，Audacity 團隊一直為錄音和清理聲音打造這個開源的應用程序。</p><p>我經常使用 Audacity，作為一個受過培訓的編輯，我已經習慣了在我的應用程序中使用重要的、通常是單鍵的鍵盤快捷鍵。通過圍繞單個字母建立快捷鍵，你可以一隻手放在鼠標上，一隻手放在鍵盤上，所以選擇一個工具或一個重要功能和點擊鼠標之間的延遲僅僅是幾毫秒而已。在本文中，我將專門給出我在 Audacity 中使用的鍵盤快捷方式，如果你想優化自己的設置可以參考。</p><h3 id="在-linux-上安裝-audacity" tabindex="-1">在 Linux 上安裝 Audacity <a class="header-anchor" href="#在-linux-上安裝-audacity" aria-label="Permalink to “在 Linux 上安裝 Audacity”">​</a></h3><p>在大多數 Linux 發行版上，Audacity 都可以從你的軟件包管理器中獲得。在 Fedora、Mageia 和類似的發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install audacity</span></span></code></pre></div><p>在 Elementary、Mint 和其他基於 Debian 的發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install audacity</span></span></code></pre></div>',10)),r("p",null,[t[1]||(t[1]=i("然而，我是以 ",-1)),u(a,{href:"https://opensource.com/article/21/11/how-install-flatpak-linux"},{default:l(()=>[...t[0]||(t[0]=[i("Flatpak",-1)])]),_:1}),t[2]||(t[2]=i(" 方式來使用 Audacity 的。",-1))]),r("p",null,[t[4]||(t[4]=i("在 Windows 或 macOS 上，可以從 ",-1)),u(a,{href:"https://www.audacityteam.org/"},{default:l(()=>[...t[3]||(t[3]=[i("Audacity 網站",-1)])]),_:1}),t[5]||(t[5]=i(" 下載一個 Audacity 安裝程序。",-1))]),r("p",null,[t[7]||(t[7]=i("它最近有一個叫做 ",-1)),u(a,{href:"https://github.com/tenacityteam/tenacity"},{default:l(()=>[...t[6]||(t[6]=[i("Tenacity",-1)])]),_:1}),t[8]||(t[8]=i(" 的復刻版本，是另外的開發者團隊準備延續 Audacity 的傳統而開發的。在寫這篇文章的時候，兩者基本上是相同的應用程序，所以這篇文章同樣適用於兩者。以後是否在功能上有分歧，還有待觀察。",-1))]),t[52]||(t[52]=e('<p>安裝後，從你的應用程序或活動菜單中啓動該應用程序。</p><h3 id="在-audacity-中設置輸入" tabindex="-1">在 Audacity 中設置輸入 <a class="header-anchor" href="#在-audacity-中設置輸入" aria-label="Permalink to “在 Audacity 中設置輸入”">​</a></h3><p>首先，你必須設置你的音頻 <em>輸入</em>，以便 Audacity 接收你使用的麥克風或音頻接口的信號。你選擇什麼輸入取決於你的設置和你擁有的音頻外圍設備。USB 麥克風通常被標為 <ruby>麥克風<rt> Microphone</rt></ruby>，但帶有 1/8&quot; 輸入插孔的麥克風可能被標為 <ruby>線路輸入<rt>Line in</rt></ruby>。你可以選擇不同輸入：</p><h4 id="pulse-audio-音頻服務器" tabindex="-1">Pulse Audio 音頻服務器 <a class="header-anchor" href="#pulse-audio-音頻服務器" aria-label="Permalink to “Pulse Audio 音頻服務器”">​</a></h4><p>Linux 使用<ruby>高級 Linux 聲音架構<rt>Advanced Linux Sound Architecture</rt></ruby>（ALSA）作為其聲音的後端，而 macOS 和 Windows 則使用自己的封閉框架。在 Linux 上，你可以將 Pulse Audio 音頻服務器設置為你的輸入源，將 Audacity 導向 <em>一個</em> 虛擬接口（Pulse），因此你可以從系統設置中選擇聲音輸入。這是我的首選方法，因為它將所有控制集中在一個方便的控制面板上。在一個應用程序中選擇一個麥克風，卻發現麥克風在其他地方被靜音的日子已經一去不復返了。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-sound-setting.png" alt="聲音輸入" title="Sound input"></p><h4 id="設備訪問" tabindex="-1">設備訪問 <a class="header-anchor" href="#設備訪問" aria-label="Permalink to “設備訪問”">​</a></h4><p>如果你的發行版或操作系統沒有使用 Pulse Audio 音頻服務器，或者由於某種原因你喜歡直接訪問聲音設備，你可以從下拉菜單中選擇一個設備。這需要了解你的系統是如何列出聲音設備的，這有時候並不很好找。台式機可能有幾個輸入源，有些在機箱的後面，有些在前面的面板上。筆記本電腦通常輸入方式較少，但你可能在網絡攝像頭附近有一個麥克風，如果你使用的是外部麥克風，可能還有一個。</p><h3 id="用-audacity-錄製音頻" tabindex="-1">用 Audacity 錄製音頻 <a class="header-anchor" href="#用-audacity-錄製音頻" aria-label="Permalink to “用 Audacity 錄製音頻”">​</a></h3><p>選中你的輸入後，按“<ruby>錄音<rt>Record</rt></ruby>”按鈕（有紅點的按鈕）。</p><p><img src="https://opensource.com/sites/default/files/uploads/audacity-input.png" alt="錄製音頻" title="Recording audio"></p>',11)),r("p",null,[t[10]||(t[10]=i("如果你是對着麥克風錄音，你所要做的就是開始説話。如果你從，比如説，",-1)),u(a,{href:"https://opensource.com/article/18/1/audacity-digitize-records"},{default:l(()=>[...t[9]||(t[9]=[i("黑膠唱片機",-1)])]),_:1}),t[11]||(t[11]=i(" 錄製輸入，那麼你必須啓動它。不管是什麼，只要 Audacity 處於錄音模式，任何發送到你選擇的輸入的信號都會被寫入 Audacity 並在你的屏幕上呈現為波形。",-1))]),t[53]||(t[53]=e('<p><strong>我的快捷方式：</strong> 我使用 <code>R</code> 鍵來開始錄音。默認情況下，按下空格鍵停止錄音（也可以回放錄音）。</p><h3 id="編輯音頻" tabindex="-1">編輯音頻 <a class="header-anchor" href="#編輯音頻" aria-label="Permalink to “編輯音頻”">​</a></h3><p>錄音很少完全按計劃進行。也許你過早地開始錄音，不得不忍受幾秒鐘的黑膠靜音（它就像靜音，但更嘈雜），或者你發現你的語氣停頓都是 “呃”、“嗯”或其他聲調，或者你一開始就錄製錯誤了。Audacity 首先是一個波形編輯器，這意味着你可以在最終的錄音中剪掉你不想要的聲音，就像你在文字處理器中輸入的文字一樣容易編輯。</p><h3 id="編輯過零點的聲音" tabindex="-1">編輯過零點的聲音 <a class="header-anchor" href="#編輯過零點的聲音" aria-label="Permalink to “編輯過零點的聲音”">​</a></h3><p>Audacity 的主要編輯工具是“<ruby>選擇工具<rt>Selection Tool</rt></ruby>”。它是你在文字處理程序中看到的熟悉的“工字形”光標，它的功能在這裏也是一樣。你可以點擊並拖動這個光標，穿過聲音的一個區域，然後你可以複製、粘貼、剪切、刪除或直接播放這個區域。</p><p><strong>我的快捷鍵：</strong> 我用 <code>I</code> 鍵來激活“<ruby>選擇工具<rt>Selection Tool</rt></ruby>”，因為光標看起來像字母 “I”。</p>',6)),r("p",null,[t[14]||(t[14]=i("在文字處理器中，你可以非常清楚地看到每個字母的結尾和開頭。你不可能不小心選擇和刪除一個字母的一半。然而，在現代應用程序中，聲音的 “分辨率”（稱為 ",-1)),t[15]||(t[15]=r("em",null,"採樣率",-1)),t[16]||(t[16]=i("）非常好，所以人眼很難在音頻波中找到一個清晰的斷點。Audacity 可以調整你的選擇，使你選擇的區域落在所謂的 ",-1)),r("ruby",null,[u(a,{href:"https://en.wikipedia.org/wiki/Zero_crossing"},{default:l(()=>[...t[12]||(t[12]=[i("過零點",-1)])]),_:1}),t[13]||(t[13]=r("rt",null,"zero crossing",-1))]),t[17]||(t[17]=i("，這可以避免在你做切割的地方出現微妙但明顯的突兀現象。",-1))]),t[54]||(t[54]=e('<p><img src="https://opensource.com/sites/default/files/uploads/audacity-zero-crossing.jpg" alt="過零點" title="Zero crossing"></p><p>在你做出選擇後，進入“<ruby>選擇<rt> Select</rt></ruby>”菜單，選擇 “<ruby>在過零點<rt>At Zero Crossings</rt></ruby>”。</p><p><strong>我的快捷鍵：</strong> 我使用 <code>Z</code> 鍵來調整選區到過零點，使用 <code>X</code> 鍵來刪除一個區域（它使我不必將手一直移到 <code>Del</code> 或 <code>Backspace</code> ）。</p><h3 id="騰出空間" tabindex="-1">騰出空間 <a class="header-anchor" href="#騰出空間" aria-label="Permalink to “騰出空間”">​</a></h3><p>編輯的好處是，你的最終產品不一定要與你錄製的內容一致。我曾經錄製過一些講座，甚至錄製過一些讀物的劇本，但最終因為某種原因而偏離了方向，或者遺漏了一部分重要的信息，後來在發佈前又重新編排或添加了全新的音頻。</p><p>移動所選的音頻與刪除類似，但不是刪除音頻，而是複製和粘貼所選內容，就像你在文字處理器中做的那樣 —— 使用標準的鍵盤快捷鍵複製或剪切，重新定位你的光標，然後粘貼。不過，為插入的內容騰出空間，需要在音頻時間線上留出空位，這樣你就可以錄製額外的音頻來填補你所創造的空白。為此，你可以使用“<ruby>選擇工具<rt>Selection Tool</rt></ruby>”和“<ruby>時間偏移工具<rt>Time Shift Tool</rt></ruby>”。</p><p>要在音頻中創建一個空隙，將你的“<ruby>選擇工具<rt>Selection Tool</rt></ruby>”的光標放在你想添加空隙的地方。導航到“<ruby>編輯<rt>Edit</rt></ruby>”菜單，選擇“<ruby>剪輯邊界<rt>Clip Boundaries</rt></ruby>”子菜單，然後選擇“<ruby>分割<rt>Split</rt></ruby>”。這將在你的選擇點上分割你的音頻。</p><p>激活頂部工具欄中的“<ruby>時間偏移工具<rt>Time Shift Tool</rt></ruby>”（圖標是兩個連接的箭頭，分別指向左邊和右邊），點擊並拖動分割後的音頻的右半部分，創建一個間隙。</p><p><img src="https://opensource.com/sites/default/files/uploads/audacity-split.jpg" alt="空隙" title="Spacer"></p><p><strong>我的快捷方式：</strong> 我用 <code>K</code> 來分割，用 <code>T</code> 來激活“<ruby>時間偏移工具<rt>Time Shift Tool</rt></ruby>”。</p><h3 id="導出音頻" tabindex="-1">導出音頻 <a class="header-anchor" href="#導出音頻" aria-label="Permalink to “導出音頻”">​</a></h3>',11)),r("p",null,[t[19]||(t[19]=i("當你對你的音頻感到滿意時，你可以導出它，這樣你就可以與他人分享。Audacity 可以選擇它能夠導出的格式，並且它能夠將其輸出到像 ",-1)),u(a,{href:"https://opensource.com/article/21/11/linux-line-commands-reclaim-space-converting-files#audio"},{default:l(()=>[...t[18]||(t[18]=[i("ffmpeg",-1)])]),_:1}),t[20]||(t[20]=i(" 這樣的工具，以獲得比你可能永遠需要的更多格式。",-1))]),r("p",null,[t[22]||(t[22]=i("我更喜歡用 FLAC 格式輸出音頻，這種音頻格式有點像 WAV，只是它是無損壓縮的。它只佔用一小部分空間，而沒有任何質量上的損失。要嘗試它，去“",-1)),t[23]||(t[23]=r("ruby",null,[i("文件"),r("rt",null,"File")],-1)),t[24]||(t[24]=i("”菜單，選擇“",-1)),t[25]||(t[25]=r("ruby",null,[i("導出"),r("rt",null,"Export")],-1)),t[26]||(t[26]=i("”子菜單，然後選擇“",-1)),t[27]||(t[27]=r("ruby",null,[i("導出音頻"),r("rt",null,"Export Audio")],-1)),t[28]||(t[28]=i("”。有了 FLAC 文件作為你的 ",-1)),u(a,{href:"https://opensource.com/article/19/7/what-golden-image"},{default:l(()=>[...t[21]||(t[21]=[i("黃金鏡像",-1)])]),_:1}),t[29]||(t[29]=i("，你可以用 SoundConverter 把你的文件轉換成任何數量的傳輸目標的最佳格式 —— 用於瀏覽器的 Ogg Vorbis 或 Opus 或 Webm，用於蘋果設備的 M4A 文件，也許還有用於傳統系統的 MP3。",-1))]),r("p",null,[t[31]||(t[31]=i("如果你只是想從 Audacity 快速簡單地導出，簡單的選擇是 Ogg Vorbis。這是一種開源的文件格式，可以在大多數網頁瀏覽器（Firefox、Chromium、Chrome、Android 和 Edge）和 ",-1)),u(a,{href:"https://opensource.com/article/21/2/linux-media-players"},{default:l(()=>[...t[30]||(t[30]=[i("如 VLC、mpv 等媒體播放器",-1)])]),_:1}),t[32]||(t[32]=i(" 播放。",-1))]),t[55]||(t[55]=r("h3",{id:"探索-audacity",tabindex:"-1"},[i("探索 Audacity "),r("a",{class:"header-anchor",href:"#探索-audacity","aria-label":"Permalink to “探索 Audacity”"},"​")],-1)),r("p",null,[t[34]||(t[34]=i("Audacity 是開源軟件世界中的一個經典動力工具。基本的錄音和編輯僅僅是個開始。你可以添加效果、",-1)),u(a,{href:"https://opensource.com/life/14/10/how-clean-digital-recordings-using-audacity"},{default:l(()=>[...t[33]||(t[33]=[i("過濾掉（一些）噪音",-1)])]),_:1}),t[35]||(t[35]=i("、調整速度、改變音高等等。無論你是在學校錄製講座、混合鼓循環、為視頻遊戲拼接聲音，還是隻是在探索音頻世界，都可以去啓動 Audacity，發揮創意！",-1))]),t[56]||(t[56]=r("hr",null,null,-1)),r("p",null,[t[37]||(t[37]=i("via: ",-1)),u(a,{href:"https://opensource.com/article/21/12/audacity-linux-creative-app"},{default:l(()=>[...t[36]||(t[36]=[i("https://opensource.com/article/21/12/audacity-linux-creative-app",-1)])]),_:1})]),r("p",null,[t[42]||(t[42]=i("作者：",-1)),u(a,{href:"https://opensource.com/users/seth"},{default:l(()=>[...t[38]||(t[38]=[i("Seth Kenlon",-1)])]),_:1}),t[43]||(t[43]=i(" 選題：",-1)),u(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[39]||(t[39]=[i("lujun9972",-1)])]),_:1}),t[44]||(t[44]=i(" 譯者：",-1)),u(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[40]||(t[40]=[i("wxy",-1)])]),_:1}),t[45]||(t[45]=i(" 校對：",-1)),u(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[41]||(t[41]=[i("wxy",-1)])]),_:1})]),r("p",null,[t[48]||(t[48]=i("本文由 ",-1)),u(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[46]||(t[46]=[i("LCTT",-1)])]),_:1}),t[49]||(t[49]=i(" 原創編譯，",-1)),u(a,{href:"https://linux.cn/"},{default:l(()=>[...t[47]||(t[47]=[i("Linux中國",-1)])]),_:1}),t[50]||(t[50]=i(" 榮譽推出",-1))])])}const C=o(p,[["render",y]]);export{k as __pageData,C as default};
